  [1218466384198912] = "O conjunto de chá prateado brilhante é esculpido com lindos emblemas, tornando a hora do chá da tarde ainda mais elegante.",
  [1218466384198656] = "Um estudo de pintura a óleo de um artista famoso; cada pincelada conta uma história.",
