  [611399063857920] = "Após o uso, obtenha o título: <Highlight> Sequência Companion </>",
  [1200668845060608] = "Essa pessoa já enfrentou a morte, mas milagrosamente sobreviveu aqui.",
  [1200668845060352] = "Os babuínos de cabelos cacheados não conseguem falar, mas parecem ter reconhecido você.",
  [1200668845054976] = "A vitória abaixa a cabeça, o Dragão Gigante rasteja e o mundo será fruto da jornada.",
  [1200668845053440] = "Deus concede graça e usa a coroa da noite eterna em sua cabeça. De agora em diante, a longa noite não tem fim, apenas porque você está no fim dela.",
  [1200668845053184] = "Nas profundezas da longa e escura noite, Ele usa a noite como um manto de plena honra, dando-lhe a sobriedade e a paz para ficar longe da loucura, independente depois da longa e profunda noite.",
  [1200668845052928] = "É a estrela da madrugada e também a primeira luz do fim da noite. O Anjo que difunde a Sua graça divina desceu aqui.",
  [1200668845052672] = "Deus misericordioso que governa o sono e o silêncio, Ele concede esta honra a você - de agora em diante, seu nome fica fora de todo clamor.",
  [1200668845052416] = "Título exclusivo do jogador HaoYouKuaiBao",
  [1200668845052160] = "Título exclusivo do jogador bilibili",
  [1200668845051904] = "Título exclusivo do Taptap Player",
  [1200668845051648] = "Título exclusivo do jogador do site oficial",
  [1200668845050368] = "Capitão, olhe, salvamos Tingen mais uma vez.",
  [1200668845050112] = "Esperarei eternamente, esperando que a juventude passe, que a carne se decomponha, esperando a primavera quando me reunir com você.",
  [1200668845049856] = "Sei que estou caminhando com a morte, sei que estou caminhando com a vida.",
  [1200668845049600] = "O vinho envenenado mais doce, o mel que mais desgasta os ossos. Você está apenas tomando um gole ou não consegue parar?",
  [1200668845049344] = "Comer melão, comprar melão, melão fresco, quer uma fatia? Este melão está maduro? Claro, não acredite em mim, experimente... Mmm, que sorte, é um melão de reviravolta na história!",
  [611399600660224] = "Saúde vibrante e afinidade natural.",
  [611399063589888] = "Um dos produtos do Castle Workshop, pode ser utilizado para: aquisição do Castle Market, Railroad Tycoon.",
  [1200668845036032] = "A Torrente do Conhecimento varre cada equipamento vapor, tocando uma melodia única no rugido – é o desejo de pousar na lua, o movimento da vitória na batalha.",
  [611399600660480] = "Informação fragmentada e o conceito de Demise.",
  [1200668845035520] = "O Steam Palace está rugindo. Depois que uma cidade a vapor se libertou dos projetos e ganhou vida, esse núcleo ininterrupto ainda pulsa pelo sonho de pousar na Lua de cem anos atrás.",
  [611399063604480] = "Use para converter uma sala de voz de jogo em uma sala permanente e adicionar 30 dias de duração permanente.",
  [949979120148480] = "Flor Verde",
  [949979120148224] = "Estatueta de papel lunar",
  [949979120147968] = "Furacão Machado",
  [949979120146944] = "Lâmpada que realiza desejos",
  [949979120145664] = "Fio de cabelo tranquilo",
  [949979120144640] = "Trevo de quatro folhas",
  [949979120144128] = "Prova de Glória",
  [611399063782656] = "Ossos centrais contendo a coragem de acolher a luz, que pode ser usada para dissipar o horror ou fortalecer a vontade.",
  [611399063707392] = "Desbloqueia <Highlight> Ação Social Única: Vigilante </> ao usar; aquisições duplicadas serão automaticamente decompostas em Soles vinculados.",
  [611399063707648] = "Desbloqueia <Highlight> Ação Social Única: Rir </> ao usar; aquisições duplicadas serão automaticamente decompostas em Soles vinculados.",
  [611399600745728] = "Memórias suficientemente profundas às vezes permanecem de maneiras inesperadas. Eles podem salvá-lo em um momento específico ou empurrá-lo para o abismo.",
  [611399600745472] = "Quando o tempo passa por certos lugares, ele deixa depósitos. Ouça em silêncio; talvez você possa ouvir um suspiro acima da névoa cinzenta entre aqueles grãos de areia.",
  [611399600745216] = "O tempo silencia mas deixa rastros; nem mesmo a morte pode apagar os vestígios. Porém, se alguém for esquecido pelo mundo, esse é o verdadeiro sono eterno.",
  [611399600744960] = "Este é o extraordinário e também o traço da divindade. Todas as coisas têm divindade, todas as coisas nascem desde o início e Sua marca também está entre todas as coisas.",
  [611399600744704] = "As pessoas estudam história para aprender a verdade através de âncoras. Contudo, a única verdade que as pessoas aprendem com a história é: a história sempre se repete.",
  [611399600744448] = "Espiritualidade está devidamente armazenado na pedra, aguardando o momento do toque.",
  [611399600741888] = "Feito de pergaminho antigo dourado claro. Sempre que um novo nome for gravado nele, um fluxo de luz aparecerá acima do firmamento, condensando-se em uma escultura que simboliza a glória.",
  [611399600741632] = "<Highlight> Artesanato: </> Lã Fina de Cabelo de Camelo · Corte Slim · Traje Formal de Teatro \n O público está sempre nos bastidores, observando silenciosamente os aplausos de todos os dramas, discernindo a direção de todos os personagens.",
  [611399600741376] = "<Highlight> Artesanato: </> Armadura de Santo · Borda da Luz Solar · Armadura Sagrada Drapeada \n Uma alma que é sincera e pura será tão sagrada quanto a luz do sol; quando você canta com o coração vermelho, o Sol também acenará para você.",
  [611399600741120] = "<Highlight> Artesanato: </> Couro gravado · Armadura leve com rebite prateado · Armadura leve de batalha \n O crepúsculo nunca fluindo permanece nas ombreiras; mesmo que este corpo seja banhado pelo sol poente, ainda existe a ambição de despertar o amanhecer.",
  [611399600740864] = "<Highlight> Artesanato: </> Linho Fiado Fino · Página em Relevo · Robe com Frente Aberta \n Mantenha admiração em seu coração, espie o misterioso, e somente quando este corpo compreender a verdade de todas as coisas ele poderá cessar.",
  [611399600740608] = "<Highlight> Artesanato: </> Cinza Neblina Fiado Fino · Jacquard Padrão Escuro · Adivinhação Vestuário \n Mesmo quando as grandes mudanças do destino chegarem, não se esqueça de levantar os cantos da boca e zombar dela.",
  [611399600740352] = "<Highlight> Artesanato: </> Lã Fina Stardust · Padrão de Jornada · Conjunto de Capa Curta \n O céu estrelado é vasto e todas as portas podem ser alcançadas. Usando isso, que a luz das estrelas da jornada guie você para nunca se perder.",
  [611399600738560] = "A conta não desapareceu; acabou de ser transferido para alguém mais adequado para pagar.",
  [611399600738304] = "Os pontos da trama atingiram 800",
  [611399600733696] = "Licor suave e perfumado, fluindo silenciosamente.",
  [611399600730112] = "Uma pequena garrafa selada feita de vidro preto, com antigas runas de selamento de Feynapotter gravadas na parede interna, supostamente suprimindo a aura verdadeiramente do Abismo armazenado dentro dela. Quando a garrafa é quebrada, o eco condensado na garrafa se espalha repentinamente, envolvendo a área circundante e fazendo com que as mentes de quem entra em contato com ela tremam violentamente. Só pode ser usado uma vez, não é possível restaurar a garrafa.",
  [611399600729856] = "Resíduos que sobram depois que um Beyonder prepara uma poção, geralmente descartados. Não sei quem começou a coletá-lo e engarrafá-lo, fazendo-o circular no mercado negro a um preço baixíssimo. Tem um cheiro indescritível de peixe, comparável ao cheiro de peixe-lobo enlatado – você tem algum inimigo? Você pode recomendar que eles experimentem.",
  [611399600729600] = "Uma invenção do Imperador Roselle. Diz-se que a inspiração veio de uma fórmula refrescante de sua cidade natal. Com óleo essencial de hortelã-pimenta como base, misturado com sete ervas que combatem a aura de corrupção – há rumores de que esse nome corresponde aos “Sete Deuses Ortodoxos”. Embalado em um pequeno frasco de metal, pode ser usado a qualquer momento; basta abrir a garrafa e aproximá-la do nariz, e aquele aroma fresco pode dissipar instantaneamente a confusão mental provocada pela corrupção. \n\n Não importa quando ou onde, é sempre muito eficaz e a um preço barato, sempre pode salvar alguém no momento mais desgrenhado.",
  [611399600729344] = "Usado para distribuir recompensas pelos assentos escolhidos por Deus no servidor estratégico.",
  [611399600728320] = "Uma matriz irregular de vários lados que libera uma aura escura, com um brilho roxo escuro fluindo entre as bordas. Quando rolado, ele irá parar no ar por meio suspiro, como se estivesse tomando uma decisão. Então cai para o lado que escolheu.",
  [611399600728064] = "Um dado irregular de múltiplas faces que emite um brilho dourado, quente ao toque, como se algo estivesse girando lentamente por dentro com consciência. Quando você o segura e rola, parece que o destino se inclina ativamente naquele momento, favorecendo o próximo ponto de pouso.",
  [611399600727808] = "Um moderno dispositivo de painel de luz na ópera que permite que Beyonders e artistas estabeleçam uma conexão.",
  [611399600726016] = "Uma página em branco descendo acima da névoa cinzenta, injetada com espiritualidade pelo poder do destino. Quando duas alianças ressoarem, o texto oculto aparecerá.",
  [611399600723200] = "Um líquido misterioso contido em uma garrafa de vidro. Diz-se que quem bebe pode esquecer temporariamente as habilidades que já aprendeu, fazendo assim uma nova escolha na encruzilhada do destino.",
  [611399600722944] = "“As transações nunca são gratuitas, mas o contrato garante que não quebrará a sua palavra.”",
  [611399600714752] = "Um dos vasos rituais icônicos da Igreja do Sol Ardente Eterno, usando um processo especial para selar uma pequena quantidade do sagrado espiritualidade do Sol Caminho em um distintivo banhado a ouro. Mesmo na escuridão, o raio de luz proveniente da medalha permanece real: aqueles ao redor do usuário sentirão um calor silencioso e uma sensação de ordem, fazendo com que a turbulência mental tenda a se estabilizar e permitindo que a mente se acalme novamente após o caos.",
  [611399600450048] = "Uma brisa coletada de uma fenda no Mundo Espiritual.",
  [611399600700672] = "Quando duas almas caminham lado a lado na trajetória do destino, esse brilho se condensará nas profundezas da névoa cinzenta. Não registra o conteúdo da aliança, apenas o caminho percorrido juntos.",
  [611399600697856] = "Um fragmento da realidade solidificado no longo rio da história, contendo parte da essência do próprio Artefato Selado. Usá-lo tornará a projeção infinitamente próxima da realidade, ao custo do perigo também descer junto com ela.",
  [611399600697600] = "Um leve eco de uma projeção histórica, registrando fragmentos do antigo poder do Artefato Selado. Use-o para despertar a projeção adormecida e deixar o perigo revelar gradualmente sua verdadeira forma.",
  [611399600673280] = "Uma bola de cristal transparente do tamanho de um punho, dentro da qual a luz e a sombra que fluem parecem estar seladas. Toque levemente no cristal e aqueles elegantes passos de dança reaparecerão em sua mente, como se sua alma tivesse experimentado pessoalmente aquela performance. E a essência da arte é transformar o momento em eternidade.",
  [611399600666112] = "Companheiros caminhando lado a lado, lembrem-se da Aliança de caminhar juntos!",
  [611399600665856] = "Viajante que atravessou o desconhecido, aceite a glória proporcionada pela distância!",
  [611399600663296] = "Vários movimentos do Fantasma da Ópera; após a compra, eles podem ser usados ​​para apresentações dentro do Fantasma da Ópera.",
  [611399600663040] = "Um token comum da Câmara de Comércio, que pode ser utilizado para o comércio de cargas.",
  [611399600662784] = "O presentinho favorito de Marmos, que pode efetivamente restaurar suas energias.",
  [611399600662016] = "Este é um item temporário.",
  [611399600661248] = "Os laços mais profundos começam com a menor certeza. E toda certeza vale a pena valorizar.",
  [611399600660992] = "A respiração das plantas e das árvores transformou-se num silêncio líquido, com palavras adormecidas dentro dele.",
  [611399600660736] = "O que está enrolado não é apenas papel, mas espaço-tempo dobrado e tabus.",
  [1200668845035776] = "Quando o Imperador Roselle pousou na Lua, ele não viajou nesta cidade a vapor - mas o Palácio a Vapor nasceu para isso e ficou em silêncio por isso. Algumas ótimas ideias, mesmo que não escolhidas, merecem ser lembradas.",
  [1200668845049088] = "Você que se reencontra no Reino de Deus certamente terá seus sonhos realizados.",
  [611399600659968] = "Pode ver através de disfarces ou criar ilusões.",
  [611399600659712] = "Sussurros da floresta, armazenados nos anéis das árvores.",
  [611399600659456] = "Ressonando com antigas frequências de inspiração.",
  [611399600659200] = "Pode capturar fragmentos remanescentes de pensamento.",
  [611399600658944] = "Emitindo fracas flutuações espirituais.",
  [611399600658688] = "Pulso selvagem de reação rápida.",
  [611399600658432] = "Pode capturar imagens de memórias e do futuro próximo.",
  [611399600658176] = "Possui o espiritualidade para rastrear e travar alvos.",
  [611399600657920] = "Tocá-lo pode bloquear rapidamente o fluxo do espírito.",
  [611399600657664] = "Um pedaço de nitidez arrancado das sombras, ainda capaz de cortar a realidade.",
  [611399600657408] = "Padrões milenares transformados em pó, as barreiras do tempo se dissipam na ponta dos dedos.",
  [611399600657152] = "A frequência de pulso é extremamente alta, cheia de poder primitivo.",
  [611399600656896] = "Paciência e percepção multiangular condensadas no pulso.",
  [611399600656640] = "Força bruta primitiva, solidificada nos ossos.",
  [611399600656384] = "O sono e a estimulação são equilibrados num toque de fragrância.",
  [611399600656128] = "Gravar memórias que outros não desejam que sejam conhecidas.",
  [611399600655872] = "Pode amplificar a frequência da fonte da Maldição.",
  [611399600655616] = "Possui o traço de corrupção dos sonhos.",
  [611399600655360] = "O líquido preto flui no cristal, como ressentimento solidificado.",
  [611399600655104] = "Durma com isso e você verá os pesadelos de outras pessoas.",
  [611399600654848] = "Remova a sujeira para se tornar um recipiente seguro.",
  [611399600654592] = "As cores mudam, perturbando a percepção.",
  [611399600654336] = "Capaz de rasgar a escuridão, simbolizando a determinação do amanhecer.",
  [611399600654080] = "A amargura purificada pelo luar pode curar Traumas.",
  [611399600653824] = "Moonlight e Berserk coexistem na palma da mão.",
  [611399600653568] = "Duro e quente, um recipiente de coragem.",
  [611399600653312] = "A Prova de Glória, entrelaçada com causalidade.",
  [611399600653056] = "Afiada como sempre, a intenção de matar não se dissipou.",
  [611399600652800] = "Pode sentir a pulsação da selvageria quando tocado.",
  [611399600652544] = "Sangue prateado, frio mas quente.",
  [611399600652288] = "Pode ouvir o perigo de diferentes direções.",
  [611399600652032] = "Forte o suficiente para quebrar rocha.",
  [611399600651776] = "Carregando o peso da Vitória e da causalidade.",
  [611399600651520] = "A luz roxa pode pacificar emoções inquietas.",
  [611399600651264] = "Amargo o suficiente para deixar alguém sóbrio.",
  [611399600651008] = "A selvageria e a razão lutam no sangue.",
  [611399600650752] = "Mantendo a memória instintiva da Caçada.",
  [611399600650496] = "Cada batida é como o rugido dos tambores de guerra.",
  [611399600650240] = "Guarda Negra, selando o que não deveria ser liberado.",
  [611399600649984] = "Encontrar uma aura equilibrada no estado Berserk.",
  [611399600649728] = "Ainda batendo levemente, exalando desafio.",
  [611399600649472] = "Sangue preto, temperatura corporal anormalmente alta.",
  [611399600649216] = "Desejo primitivo de matar, solidificado na queratina.",
  [611399600648960] = "Os alunos refletem um mundo distorcido.",
  [611399600648704] = "Três formas que representam fluxo, quietude e solidificação.",
  [611399600648448] = "Flores entrelaçadas, fortalecendo laços invisíveis.",
  [611399600648192] = "A prata fluida é o sangue da alquimia.",
  [611399600647936] = "Vinte e dois anos são suficientes para que o destino deixe uma marca.",
  [611399600647680] = "A obsessão dos mortos é mais teimosa que a dos vivos.",
  [611399600647424] = "A sabedoria e a perda de controle são apenas uma linha tênue de separação.",
  [611399600647168] = "Chamas de alta concentração podem inflamar dormentes espiritualidade .",
  [611399600646912] = "Diz-se que é capaz de ver vários ângulos ao mesmo tempo.",
  [611399600646656] = "As vinhas que perderam a vitalidade ainda tentam se entrelaçar.",
  [611399600646400] = "A resiliência das trepadeiras está depositada no pó.",
  [611399600646144] = "Permanece intacto sob forte pressão.",
  [611399600645888] = "Um visitante de além do céu, os restos mortais após a queda.",
  [611399600645632] = "Ser breve ao extremo é ser eterno.",
  [611399600645376] = "Enrole em uma bola, conectando fios invisíveis.",
  [611399600645120] = "Resistência e Guarda estão escondidas na fragrância amadeirada.",
  [611399600644864] = "A velocidade é solidificada no líquido salgado.",
  [611399600644608] = "Runas incompreensíveis estão gravadas na parede interna.",
  [611399600644352] = "Mudará o padrão de crescimento das plantas vizinhas.",
  [611399600644096] = "Uma simbiose perturbadoramente bela.",
  [611399600643840] = "A superfície da água ocasionalmente reflete cenas que não deveriam existir.",
  [611399600643584] = "Puro e macio como lã de ovelha, capaz de estabilizar limites.",
  [611399600643328] = "Olhe para isso por muito tempo e você esquecerá quem você é.",
  [127888019949056] = "Cabelo Réquiem",
  [611399600643072] = "A ganância é digerida no estômago, transformando-se em cristais.",
  [611399600642816] = "Fios de cabelo úmidos exalando a pressão do mar profundo.",
  [611399600642560] = "Escuridão mais profunda que a Datura comum.",
  [611399600642304] = "O sangue muda constantemente de cor no tubo de ensaio.",
  [611399600642048] = "Um cristal de mistério e mudança, ainda tentando se transformar.",
  [611399600641792] = "Quando tocada, a pele se contorce involuntariamente.",
  [611399600641536] = "A fragrância é sufocante e a realidade começa a se distorcer.",
  [611399600641280] = "Vagando entre o sólido e o líquido, nunca tenho certeza.",
  [611399600641024] = "Líquido branco leitoso que se transforma em uma névoa fina ao entrar em contato com o ar.",
  [611399600640768] = "Padrões misteriosos brilham no líquido, como uma tatuagem viva.",
  [611399600640512] = "Enraizado na neblina, absorvendo o ilusório e o real.",
  [611399600640256] = "Golden Shelter, escondido em pó fino.",
  [611399600640000] = "Luz corrompida, sombras se espalhando pelas bordas.",
  [611399600639744] = "Seiva alucinógena, incapaz de distinguir a realidade dos sonhos.",
  [611399600639488] = "O rosto adormecido entre as pétalas é o reflexo de uma alma.",
  [611399600639232] = "A dádiva da Cordilheira Hornacis, pesada como o destino.",
  [611399600638976] = "Pó vermelho flutua ao vento, tão quente quanto o hálito de um dragão.",
  [611399600638720] = "Linda e mortal, uma gota é suficiente para fazer tremer a alma.",
  [611399600638464] = "O sabor da sobriedade pode dissipar a névoa.",
  [611399600638208] = "Uma fragrância que só floresce no escuro.",
  [611399600637952] = "Um céu estrelado solidificado está escondido no corpo.",
  [611399600637696] = "O peso do fundo do mar está depositado no sangue.",
  [611399600637440] = "Três meses de Olhar, e mais um completo você se acomodou no espelho.",
  [611399600637184] = "Na polpa escura, o veneno e a escuridão são depositados juntos.",
  [611399600636928] = "A casca da árvore se transforma em pó e o ar se enche do som de sinos ilusórios.",
  [611399600636672] = "A sangue frio, o instinto primitivo de caça se instala.",
  [611399600636416] = "No momento em que você morde a casca, o som de sinos de vento ilusórios ecoa em sua mente.",
  [611399600636160] = "A frieza profunda na medula óssea abriga uma paciência mortal.",
  [611399600449792] = "Uma pena que emite uma luz fraca, leve como nada, com uma sensação sutil da bênção divina contida dentro dela.",
  [611399600635648] = "O som de um batimento cardíaco fica selado na fragrância.",
  [611399600635392] = "A textura da casca da árvore é a impressão digital do tempo.",
  [611399600635136] = "O sangue distorceu a luz no tubo de ensaio.",
  [611399600634880] = "Cada gole equivale a cem anos.",
  [611399600634624] = "Quando olha para você, quem você vê?",
  [611399600634368] = "Branco não contaminado pela poeira é a intenção original da natureza.",
  [611399600634112] = "A memória do dente do dragão está depositada nas folhas da grama.",
  [611399600633856] = "O ponto de partida da vida, escondido numa casca dura.",
  [611399600633600] = "A velocidade é solidificada no líquido transparente.",
  [611399600633344] = "Sete cores giram no cérebro, sem parar.",
  [611399600633088] = "O sopro da floresta, condensado em flor.",
  [611399600632832] = "Pó amargo que pode anestesiar a dor.",
  [611399600632576] = "Lindo veneno, fazendo a vida estagnar.",
  [611399600632320] = "Somente sendo puro até o nada ele pode carregar tudo.",
  [611399600632064] = "Uma mistura de duas vidas, lutando no sangue.",
  [611399600631808] = "Certa vez, viu os segredos mais sombrios do fundo do mar.",
  [611399600631552] = "Sussurros perto da água são encapsulados em verde.",
  [611399600631296] = "Luz e sombra alcançam uma reconciliação na borda das pétalas.",
  [611399600631040] = "A luz flui no líquido, conectando dois mundos.",
  [611399600630784] = "Esta pena uma vez roçou os limites do Mundo Espiritual.",
  [611399600630528] = "As raízes das árvores lembram a história por mais tempo do que os humanos.",
  [611399600630272] = "O abraço do fogo e da terra, eterno no resfriamento.",
  [611399600630016] = "O pó dourado é uma clareza solidificada.",
  [611399600629760] = "A fragrância é como a luz, capaz de brilhar nas dobras da alma.",
  [611399600629504] = "Na escuridão, esta gota de sangue ainda queima.",
  [611399600629248] = "Ela cresce na fenda entre a realidade e o Mundo Espiritual.",
  [611399600628992] = "Colhida após o primeiro canto, trazendo consigo a possibilidade do sol nascer.",
  [611399600628736] = "O calor da fé ainda permanece na superfície do objeto.",
  [611399600628480] = "A doçura mortal é a porta estreita para o extraordinário.",
  [611399600628224] = "A fronteira entre a luz e a fermentação, onde o sagrado é nutrido no mundano.",
  [611399600627968] = "Um vulcão ainda pulsando, queimando a sanidade do titular.",
  [611399600627712] = "A luz solar está aprisionada na pedra, ainda tentando se libertar.",
  [611399600627456] = "As sombras profundas da floresta escondem os segredos da natureza.",
  [611399600627200] = "O presente de julho, deixando espiritualidade fluir como vinho.",
  [611399600626944] = "A luz solar de um verão inteiro é armazenada nas folhas.",
  [611399600626688] = "O acúmulo de tempo permite que coisas comuns carreguem o extraordinário.",
  [611399600626432] = "Quando o vento passa, ele imita os sussurros do vento.",
  [611399600626176] = "Durante a oração do meio-dia, as pétalas se transformaram em cristal.",
  [611399600625920] = "Conhecimento é Poder, e a fórmula é a chave do poder.",
  [611399600625664] = "As armas mudam de mil maneiras, mas a intenção de matar permanece inalterada.",
  [611399600625408] = "Nas brechas da batalha, acumule para a próxima explosão.",
  [611399600625152] = "A terra está silenciosa, mas responderá a passos suficientemente pesados.",
  [611399600624896] = "Os rituais são pactos entre humanos e misteriosos, e os pactos exigem testemunhas.",
  [611399600624640] = "O combate não é apenas uma competição de força, mas uma luta pela visão.",
  [611399600624384] = "Alguns segredos só podem ser escritos em lugares que não podem ser vistos.",
  [611399600624128] = "As estrelas já escreveram a resposta há muito tempo; depende apenas se você está disposto a ouvir.",
  [611399600623872] = "Realidade e ilusão são apenas um pensamento à parte.",
  [611399600623616] = "O que está atrás da Porta? Mesmo a própria chave não sabe.",
  [611399600623360] = "As palavras têm poder, especialmente aquelas escritas no coração.",
  [611399600623104] = "O coração humano é o silêncio mais clamoroso.",
  [611399600622848] = "O coração humano é difícil de compreender, mas as cores nunca mentem.",
  [611399600622592] = "Em nome do Sol, purifique tudo o que é impuro.",
  [611399600622336] = "A luz iluminará a verdade e também queimará mentiras.",
  [611399600622080] = "A escuridão antes do amanhecer é a mais fria, mas sempre vale a pena esperar pelo primeiro raio de luz.",
  [611399600621824] = "Uma vida por uma vida, um papel por uma pessoa.",
  [611399600621568] = "Tudo no mundo não passa de uma peça; você e eu somos atores, não precisa ser tão sério.",
  [611399600621312] = "O destino não mente; adivinhação é o meio que os humanos usam para lê-lo.",
  [611399600620800] = "Assine esta escritura para modificar o nome que você usa no mundo.",
  [611399600620544] = "Uma página arrancada de um antigo livro de profecias, reescrita por causa de suas conquistas em batalha.",
  [611399600620288] = "Cada mudança de nome é uma remodelação secreta, o que significa que o clube anunciará sua existência novamente com um visual totalmente novo.",
  [611399600620032] = "Jogo de chá feito de porcelana pura, artesanato requintado, quente ao toque, transmitindo elegância enquanto saboreia o chá.",
  [611399600619776] = "Chá preto de primeira linha, preferido pelos nobres, com sabor suave e uma doçura levemente persistente.",
  [611399600619520] = "Pudim de caramelo rico e sedoso, textura delicada, sabor doce.",
  [611399600619264] = "Aparência dourada deslumbrante, escrita suave, destacando sabedoria e bom gosto.",
  [611399600619008] = "Delicado artesanato em estampagem de prata, elegante e nobre, o transportador perfeito para cartas.",
  [611399600618752] = "Feito de latão requintado, leve e clássico, um excelente companheiro de leitura.",
  [611399600618496] = "Um perfume único elaborado a partir dos dons de criaturas marinhas, exalando uma fragrância misteriosa e suave.",
  [611399600618240] = "Extraindo fragrância natural de rosa, florescendo em todas as estações.",
  [611399600617984] = "Cultivado em Feynapot apaixonado, de cor dourada, simbolizando felicidade.",
  [611399600617728] = "Um anel feito de um raro rubi de sangue de pombo, rico e apaixonado, gravado com uma promessa eterna.",
  [611399600617472] = "Abotoaduras feitas de safiras de alta qualidade, a luz azul profunda que lembra as estrelas no céu noturno.",
  [611399600617216] = "As pérolas são silenciosamente incrustadas no buquê, seu brilho suave abrangendo todos os estados de espírito.",
  [611399600616960] = "Um colar feito de conchas naturais, carregando a vastidão e a liberdade do oceano.",
  [611399600616704] = "Um prisma transparente cuidadosamente cortado que pode refratar a luz e também \"refratar\" a capacidade da memória, tornando seus movimentos de performance mais ricos e coloridos.",
  [611399600616448] = "No momento em que você escreve o nome da outra pessoa, nasce um período de tempo que pertence exclusivamente a você.",
  [611399600616192] = "A tradicional “opinião do público” da ópera, expressando diferentes vozes de forma humorística; isso também faz parte do palco.",
  [611399600615936] = "Um presente elegante que floresce em uma chuva de rosas, transformando fragrâncias e aplausos em bênçãos, dedicado ao fantasma mais brilhante do palco.",
  [611399600449536] = "Fios de espiritualidade extraídos das “lacunas da história”, entrelaçados com inúmeros destinos possíveis.",
  [611399600567808] = "Escreva uma aliança e ela deverá ser cumprida. Lançar uma Habilidade de Classe durante o combate acionará automaticamente uma Notarização. As pilhas de Notarização acumuladas aumentam continuamente seu Ataque e Aprimoramento de Habilidade, convertendo-se em dano adicional quando totalmente acumuladas. Contudo, uma vez dado um falso testemunho, o poder dessa habilidade é bastante reduzido.",
  [611399600567552] = "Seu efeito negativo faz com que o usuário morra pouco a pouco. O Artefato Selado suprime os inimigos próximos, fazendo com que seus efeitos positivos tenham uma chance de falhar, enquanto inflige ferimentos graves intermitentemente e petrifica os monstros próximos. O custo é que seus próprios Artefatos Selados também são suprimidos e sua saúde é continuamente drenada.",
  [611399600567296] = "Possui as características de um ser vivo, controlando a probabilidade de cada evento. Quando a reação de um Artefato Selado ocorrer, ele lançará um dado para você; há apenas uma chance em seis de que isso realmente caia sobre você.",
  [611399600567040] = "A equipe do Teletransporte deixada pela família Abraham. Faça uma marca de estrela no alvo; quando o alcance for insuficiente, consuma a marca para se teletransportar para a posição antes de atacar, e você pode adicionar outro teletransporte após uma esquiva. Mas quanto mais for acionado, maior será a probabilidade de você perder o controle e se perder.",
  [611399600566784] = "Colheita, riqueza e vitalidade. Depois de mantê-lo por um período de tempo, você carrega uma Maldição; quando você morre, o terreno ativado cresce no local, curando continuamente os companheiros de equipe, aumentando o Ataque e concedendo imunidade ao controle. Mas enquanto a terra existir, você não poderá ser ressuscitado.",
  [611399600566528] = "Outrora ferro de meteorito extraterrestre, agora exala uma aura decadente. Os ataques têm a probabilidade de disparar bolas de veneno corrosivas, fazendo com que o alvo murche continuamente; atacar novamente faz com que o Venom se espalhe. A corrupção do céu estrelado também retornará para você, corroendo-se continuamente.",
  [611399600566272] = "Esta luva despojará a alma do inimigo para o seu lado; depois de devorá-lo, você pode obter suas habilidades ou aprimoramentos de especialização antes de sua morte. Mas nunca está satisfeito – cada Marionete alma reduz seu limite de Saúde.",
  [611399600566016] = "Coloque-o e o Grito do submundo rasgará seus ouvidos, aumentando significativamente a velocidade de ataque e Recarga o retorno de todas as habilidades de batalha, e as mortes podem estender a duração. Mas se você ainda estiver em batalha depois de tirar a máscara, você cairá em Fraqueza.",
  [611399600565760] = "A eterna lua cheia forjada pelo ancestral dos vampiros. Aumenta o seu nível de habilidade de batalha e de seus companheiros de equipe e fortalece o Marionete ; mesmo que a habilidade esteja ativada Recarga , há uma probabilidade de invocação forçada. O preço é que cada convocação forçada devorará sua saúde.",
  [611399600565504] = "Sentindo o cheiro da batalha, o General se transformará em um Espírito Maligno. e aparecem periodicamente, rastreando a direção do Inimigo para realizar ataques de rastreamento, causando dano, atordoamento e esculpindo uma Marca do Inimigo. Mas lembre-se de ficar longe disso; o mestre também é seu inimigo.",
  [611399600565248] = "Ao entrar na batalha, a Boneca do Infortúnio aguardará uma oportunidade para causar problemas. Quando uma habilidade atinge um inimigo, o boneco irá possuí-lo, reduzindo sua defesa e resistência crítica, e transferindo conforme você troca de alvo. Quando ele retorna para você, você suporta o infortúnio.",
  [611399600564992] = "Através dele, o corpo espiritual fica claro e a realidade fica turva. Abrir Visão Espiritual em batalha pode ganhar a bênção do corpo espiritual , recuperando continuamente a Saúde e reduzindo o dano recebido, mas Visão Espiritual é mais curto e tem um Recarga mais longo. Depois que termina, a visão fica prejudicada e o bloqueio e a defesa são reduzidos.",
  [611399600564736] = "Domine a habilidade de transferir danos. Depois de ser atingido com força em um curto espaço de tempo, você pode enquadrar os outros pela maior parte dos danos subsequentes, e a intuição sobre o perigo pode evitar o controle. No entanto, a ilusão acabará por se dissipar, e as emoções amplificadas trazem sensibilidade e dor, caindo brevemente na Vulnerabilidade.",
  [611399600564480] = "Desde que a lesão não seja grave, este anel irá ajudá-lo continuamente a recuperar a saúde. Se sua saúde estiver cheia, ele irá curar o companheiro de equipe com a saúde mais baixa. Também atrai mosquitos, fazendo com que seu Escudo se dissipe com o tempo.",
  [611399600564224] = "Ao receber dano fatal, uma estatueta de papel aparecerá brevemente para suportar o dano excessivo por um período de tempo. Mas quando ele desaparece, parte desse dano ainda irá agir sobre você, tornando-o mais Frágil por um período de tempo.",
  [611399600563968] = "Exerce lentamente influência sobre unidades inimigas próximas, fazendo-as cair em estado Perdido, com movimentos lentos e membros imóveis. Se eles se atreverem a atacar você, esse infortúnio descerá mais rápido. Como titular, você também cairá intermitentemente em um estado Perdido.",
  [611399600563712] = "Segurar esta arma lhe dará o poder do vento e da eletricidade. A velocidade de movimento e a velocidade de ataque do ataque básico são aumentadas; quando um Ataque Básico acerta, existe a probabilidade de atingir o alvo com um raio, causando dano e Estagnação. Mas se você não tomar cuidado, o raio também atingirá você.",
  [611399600563456] = "Substitua sua habilidade de Limpeza pela mais poderosa “Prova de Glória”, envolvendo-se em luz espessa, ganhando Super Armadura e Redução de Dano e refletindo o dano aos atacantes próximos. No final, quebre a Cage para atordoar os inimigos. A reflexão estenderá seu Recarga .",
  [611399600563200] = "Em algumas situações especiais, talvez você possa fazer um desejo ao Gênio em troca de limite de Saúde, Recarga retorno ou Explosão de Ataque Básico. Porém, os desejos têm um preço e devem ser reembolsados ​​no futuro.",
  [611399600562944] = "Crie uma lua cheia ao seu redor. Os inimigos próximos ficarão mais lentos quando te machucarem e sua Redução de Dano aumentará; ao causar dano aos inimigos, você ganha Aumento de Dano. Se nenhum dano for causado por um período de tempo, o sangue esfria gradualmente e a resistência não pode ser recuperada.",
  [611399600562688] = "Depois de lançar Ataque Básico e habilidades, há uma probabilidade de ganhar sorte, aumentando a velocidade de movimento, acertos críticos e Aprimoramento de Habilidade, que pode ser acumulado várias vezes; se não for acionado, a probabilidade continua a se acumular. Mas quando a sorte acabar, você ficará exausto e a velocidade de movimento e a recuperação da resistência diminuirão.",
  [611399600562432] = "Depois de usar uma habilidade fonte, você pode adicionar um efeito Wind Blade aos seus ataques, aumentando a velocidade de movimento, quebra de armadura e aprimoramento de habilidade. Ao mesmo tempo, devido à terrível voz deste cantor, você receberá intermitentemente efeitos negativos como Aprisionamento, Silêncio e redução de atributos.",
  [611399600562176] = "Quando os inimigos atacam você, eles serão infectados aleatoriamente com toxinas como Paralisia e Fraqueza; quando empilhado, piora. Você também deixará uma poça de veneno quando morrer. Como detentor, as toxinas inevitavelmente evaporam em você também.",
  [611399600561920] = "Fornece escamas fantasmas escondidas sob a pele, tornando você tão difícil de capturar quanto um peixe, acumulando Redução de Dano e Quebra de Controle quando ferido. Mas depois de desembarcar, você fica cansado mais facilmente do que as pessoas comuns e o consumo de resistência acelera.",
  [611399600561664] = "Complete a derradeira alquimia da vida, utilizando o poder do crescimento vigoroso para recuperar a saúde em momentos críticos. O preço é que o corpo sofre mutações pouco a pouco e a velocidade de movimento e a defesa diminuem continuamente.",
  [611399600561408] = "O anel de ouro incrustado com rubis brilha com brilho. Quando está perto da morte, ele suga carne e sangue de inimigos próximos, ressuscitando da beira da morte uma e outra vez. Mas o preço de perder a sanidade é que ocasionalmente você ficará lento e terá velocidade de movimento reduzida durante a batalha.",
  [611399600561152] = "Um presente da Sra. Justice, dando uma sensação inexplicável de paz. Reduz o dano que você sofre e transforma o sofrimento sofrido em riqueza, aumentando a defesa com base no dano acumulado. Se a riqueza pesar sobre você por muito tempo, você ficará sobrecarregado.",
  [611399600560896] = "A luz emitida aquece você e seus companheiros de equipe próximos, aumentando seu ataque e aprimoramento de habilidades. Mas o calor próximo também queimará o suporte; depois de lançar uma habilidade fonte, você perderá saúde continuamente.",
  [611399600560640] = "Exponha a fraqueza do inimigo, aperte o gatilho após empilhar camadas, causando dano, Ferimento Grave e Atordoamento. O custo é que cada tiro requer infusão de espiritualidade e consumo de resistência, ao mesmo tempo que expõe brevemente sua própria fraqueza.",
  [611399600557312] = "Quando a névoa cinzenta surge e a bola de cristal amarela reflete as sombras de uma terra estrangeira, sempre há alguns que conseguem reconhecer a luz nos olhos uns dos outros que não pertence a esta época – esse é o entendimento tácito da mesma cidade natal.",
  [611399600552704] = "Você coletou todos os capítulos dispersos. Esse conhecimento é reunido em sua mente, construindo uma Roselle Gustav mais real do que qualquer livro de história.",
  [611399600552448] = "A maior medalha de honra concedida pela Prefeitura. Esta medalha não é apenas o fim da exploração, mas também uma comemoração: tudo o que você salvou pessoalmente para Tornar Tingen Grande Novamente. Do seu jeito.",
  [611399600552192] = "Conhecimento acumulado durante suas provações que lhe permite controlar melhor seus Beyonder poderes.",
  [611399600549376] = "Olhe atentamente, este é o “Bom Cidadão Cinco Estrelas de Tingen”. Não se importe com o lixo folheado a ouro emitido por aqueles idiotas da Prefeitura; eles não sabem de nada.",
  [611399600549120] = "Todos os pecados do lado negro têm um preço.",
  [611399600547584] = "Lembre-se, amigo, em Tingen... quando você consegue isso, você não é mais um \"bom cidadão\", mas um de nós. Bem-vindo ao mundo da verdadeira ordem. Agora venha receber sua recompensa ou saia.",
  [611399600546304] = "Um símbolo de honra obtido após participar do jogo Peak of the Gods.",
  [611399600545536] = "Duas engrenagens grossas, uma grande e outra pequena, podem ser usadas para atualizações de trem.",
  [611399600545280] = "Algumas páginas de documentos que representam a autorização da Câmara de Comércio para o acesso ferroviário, ponto de partida do sonho de um magnata dos negócios.",
  [611399600545024] = "Equivalente reconhecido pela Câmara de Comércio na jogabilidade Railway Tycoon, emitido na forma de vouchers.",
  [611399600544768] = "Quando a máscara dá nova vida à boneca, tudo pode subir ao palco para abrir a cortina para você.",
  [611399600544512] = "Poder emprestado do passado; quanto mais detalhada for a sua compreensão do histórico correspondente, maior será a probabilidade de sucesso.",
  [611399600544256] = "Conhecimento misterioso, origem desconhecida, mas solidifica o tempo e condensa a compreensão da aplicação de habilidades.",
  [611399600542720] = "Uma poção de energia especial que registra a experiência de crescimento de outros Beyonders. Após o uso, pode-se experimentar rapidamente o caminho de crescimento de outros poderosos Beyonders, permitindo-se passar rapidamente pelo período fraco e ganhar 10.000 pontos de experiência.",
  [611399600538880] = "Respire fundo, calmo e tranquilo. (Só pode carregar 3 de cada vez)",
  [611399600538624] = "As pétalas vermelho-escuras são impressionantes.",
  [611399600537088] = "\"Quando a projeção histórica de um Artefato Selado se dissipa, ele deixa um rastro de sua aura histórica única.\" \n \"Qual é a utilidade disso?\" \n \"É claro que a aura histórica pode aumentar o grau e a habilidade de um Artefato Selado, até o Grau 1, que é um estado altamente perigoso.\" \n \"Pode ser atualizado para o Grau 0?\" \n \"Nota 0? Suas cabecinhas ingênuas realmente se atrevem a pensar; pelo menos esperem até chegar ao meio Sequência antes de considerar tais coisas!\"",
  [611399600533248] = "Narrativa fragmentada para coleta de enredo.",
  [611399600532736] = "Comece um dia cheio de energia!",
  [611399600532480] = "Todo reembolso começa com a anexação adequada dos recibos.",
  [611399600532224] = "Uma bola de cristal emitindo luz roxa; simboliza a coesão do clube, bem como a sua atividade e contribuição.",
  [611399600531968] = "Pele de raposa, macia, fofa e grossa; você pode desfrutar da suavidade do veludo mesmo andando descalço.",
  [611399600531712] = "Uma bala com núcleo de aço de alta densidade, fundida pela indústria militar pesada, suficiente para perfurar armaduras pesadas e influenciar o curso de uma guerra.",
  [611399600531456] = "Oh, herói triunfante, receba os aplausos da vitória!",
  [611399600531200] = "Para testes temporários.",
  [611399600530176] = "Uma caçada de vida ou morte nas sombras da zona proibida; cada golpe é uma marca pesada no direito do caçador de sobreviver.",
  [611399600529408] = "Este é o suspiro persistente do campo de batalha e também o eco inevitável do destino.",
  [611399600528896] = "Um material especial que pode servir de base para preparar poções; esta é uma riqueza cobiçada por todos, pela qual todos lutam.",
  [611399600528640] = "Um material especial que pode servir de base para preparar poções; esta é apenas a sua vitória, que ninguém pode tirar.",
  [611399600528384] = "O sangue da presa; esta é a única marca de autoridade.",
  [611399600449280] = "Pele muda de uma criatura do Mundo Espiritual, brilhando com um leve brilho sob o luar.",
  [611399600483840] = "Uma projeção histórica de Melissa Moretti, recriando a forma e as habilidades parciais da original.",
  [611399600483584] = "Uma projeção histórica de Benson Moretti, recriando a forma e as habilidades parciais do original.",
  [611399600483328] = "Uma projeção histórica de Frank Lee, recriando a forma e as habilidades parciais do original.",
  [611399600483072] = "Uma projeção histórica de Frye Ockham, recriando a forma e as habilidades parciais do original.",
  [611399600482816] = "Uma projeção histórica do Velho Neil, recriando a forma e as habilidades parciais do original.",
  [611399600482304] = "Uma projeção histórica de Lovia Tiffany, recriando a forma e habilidades parciais do original.",
  [611399600482048] = "Uma projeção histórica de Susie, recriando a forma e habilidades parciais do original.",
  [611399600481536] = "Uma projeção histórica de Alger Wilson, recriando a forma e as habilidades parciais do original.",
  [611399600481280] = "Uma projeção histórica de Fors Wall, recriando a forma e as habilidades parciais do original.",
  [611399600481024] = "Uma projeção histórica de Audrey Hall, recriando a forma e habilidades parciais do original.",
  [611399600480768] = "Uma projeção histórica de Daly Simone, recriando a forma e habilidades parciais do original.",
  [611399600480512] = "Uma projeção histórica de Dunn Smith, recriando a forma e as habilidades parciais do original.",
  [611399600480256] = "Uma projeção histórica de Leonard Mitchell, recriando a forma e as habilidades parciais do original.",
  [611399600477696] = "Uma maravilha de transmissão que adiciona poder Beyonder extra, transformando a declaração do usuário no som de um trovão, espalhando-se rapidamente além dos Cinco Mares.",
  [611399600477440] = "Uma curiosidade de transmissão com poder adicional de Beyonder, transformando as palavras sinceras do usuário em penas quentes e flutuantes, transmitindo-as suavemente além dos Cinco Mares.",
  [611399600477184] = "Uma curiosidade de rádio confeccionada por um artesão, capaz de transmitir a voz do usuário além dos Cinco Mares.",
  [611399600475392] = "Um documento contratual amarelado, amarrado com corda de linho azul, exalando o poder da ordem; não pode ser distorcido ou destruído.",
  [611399600475136] = "Uma herança meticulosamente elaborada. O corpo é feito de mogno de primeira linha do Continente Sul, com um tom profundo e suave.",
  [611399600474880] = "Uma faca curta específica para abrir envelopes. O cabo esmaltado é incrustado com fio dourado, lindo e complexo.",
  [611399600474624] = "Feito usando artesanato de sopro de vidro com um design lindo. Adequado para cada momento que vale a pena comemorar.",
  [611399600474368] = "Feito em cerâmica grosseira, pintado no estilo tradicional do Reino de Loen, elegante e lindo.",
  [611399600472064] = "Amarre uma retórica silenciosa em volta do pescoço e dobre suas preocupações em uma flor que nunca murcha.",
  [611399600471808] = "A ternura fluindo na ponta dos dedos transforma cada toque em um momento inebriante.",
  [611399600471552] = "Um leve aceno de cabeça ao tirar o chapéu; uma cartola mostra boas maneiras.",
  [611399600471296] = "Seda fluindo com brilho perolado; usando-o, você certamente será a pérola deslumbrante da festa noturna.",
  [611399600471040] = "A caxemira de alta qualidade parece suave como uma nuvem, interpretando o luxo discreto da vida aristocrática.",
  [611399600470784] = "Como um soneto tecido ao luar, cada volta continua a escrever um movimento magnífico e inacabado.",
  [611399600470528] = "O melhor companheiro dos sonhos, conferindo ao sono uma textura linda.",
  [611399600470272] = "Feito sob medida como uma andorinha, com uma bainha traseira levemente esvoaçante que esconde um banquete não iniciado.",
  [611399600470016] = "Quando a bainha da roupa passa por um poste de luz, sempre há segredos farfalhando nas dobras.",
  [611399600469760] = "Como o abraço de um velho amigo, envolvendo uma alma delicada numa textura áspera.",
  [611399600469504] = "Costura densa com bainha larga; você não se sentirá restrito ao levantar os braços para trabalhar.",
  [611399600469248] = "Precioso como uma pérola, um presente do oceano, sabor salgado e fresco, textura crocante, sabor supremo.",
  [611399600468992] = "Espalhe camarões do mar, secos ao sol para ficarem deliciosos e frescos, e depois grelhados no carvão até obterem uma cor âmbar. Conheço o sabor do mar: camarão seco âmbar!",
  [611399600468736] = "Extraído de bordo-açucareiro, de cor dourada, xarope sedoso, com refrescante doçura amadeirada; é o companheiro perfeito para panquecas quentes.",
  [611399600468480] = "Processado a partir de leite de alta qualidade e com água filtrada, é um alimento essencial na mesa de jantar.",
  [611399600466176] = "O visual incorpora os conselhos de entusiastas de bonecas mais velhas. Pode ser usado como enfeite, brinquedo ou amigo.",
  [611399600465920] = "Uma caixa e uma boneca resistentes a quedas com uma mola que não pode ser quebrada, por mais que você a gire; projetado especificamente para crianças animadas.",
  [611399600465664] = "O interior usa material de latão resistente ao desgaste para garantir que as mãos ainda possam funcionar com precisão após uso prolongado.",
  [611399600465408] = "Uma criação de tecnologia de vapor, imensamente poderosa, com saída de vapor durante a queima; é a personificação do poder e da indústria.",
  [611399600465152] = "O cano escuro como breu é temperado com luz fria, e os padrões desgastados no punho registram vários confrontos noturnos.",
  [611399600464896] = "Relógio de pêndulo em jacarandá, elegante e solene, contendo um cuco mecânico; serviços de reparo podem ser adquiridos para ajuste de volume.",
  [611399600464640] = "Replica o clássico modelo de trem \"Thomas\"; vem com faixas na compra.",
  [611399600464384] = "Aparência requintada e compacta, com feedback tátil das teclas, a ferramenta preferida para escritores de viagens.",
  [611399600464128] = "Agite, prepare; o rico aroma do café só pode ser criado por um moedor de café manual!",
  [611399600463872] = "Uma panela de sopa doméstica forjada em ferro preto; o material pesado é adequado para sopas de inverno de cozimento lento.",
  [611399600463616] = "Feito de madeira marrom escura, barata e resistente; as lascas de madeira na superfície precisam ser manuseadas por você mesmo durante o uso.",
  [611399600463360] = "O licor vermelho-dourado é como mel fino misturado com sangue; doce e suave, mas cuidado com o excesso de indulgência.",
  [611399600463104] = "Uma especialidade destilada do norte de Loen, seu vigor violento pode dissipar qualquer vento frio e cortante.",
  [611399600462848] = "O licor cristalino é suave no paladar e a sua harmoniosa relação de sabor torna-o agradável e perfumado.",
  [611399600462592] = "A fragrância refrescante da cerveja envolta em manteiga rica; quente, suave e suave a cada gole.",
  [611399600459264] = "Fio dourado manchado com uma grande quantidade de névoa cinza, que pode ser usado para procurar Marionetes através do Teatro Utopia.",
  [611399600458240] = "Capaz de ajustar com precisão cada equipamento válvula de um carro a vapor, remodelando o estado operacional do veículo. Somente aqueles que dominam este selo são verdadeiros mestres das máquinas.",
  [611399600457984] = "Um tributário do destino, como o brilho solidificado do pôr do sol, ou como um amanhecer que nunca desaparece em algum mundo paralelo.",
  [611399600457472] = "Fatores primitivos precipitados após Beyonder materiais serem quebrados, que podem ser usados ​​como meio para Beyonder convergência.",
  [611399600457216] = "Uma lâmpada contendo um poder misterioso; uma vez acesa, pode abrir a porta do corredor da história.",
  [611399600456960] = "Uma substância estranha em estado cristalino translúcido, tremeluzindo com uma leve luz fantasmagórica, mudando frequentemente de aparência.",
  [611399600456704] = "Um cristal com brilho abrasador; usar este cristal pode revitalizar o maior potencial que o equipamento já possuiu.",
  [611399600455680] = "Quando o Mythical Cocoon nasceu em Castelo Sefirá , a névoa cinzenta também se condensou em incontáveis ​​grãos de cristal.",
  [611399600455424] = "Quando o Mythical Cocoon nasceu em Castelo Sefirá , a névoa cinzenta também levantou inúmeras poeiras.",
  [611399600455168] = "Nem todos os poderes míticos se condensam em casulos completos; alguns poderes não são fortes o suficiente e só podem se transformar em filamentos dispersos.",
  [611399600454912] = "O Sr. Tolo localizou inúmeras Criaturas Míticas da história e usou 'Enxerto' para transferir seu poder para Castelo Sefirá, obtendo Tecido Mítico.",
  [611399063830528] = "Após o uso, obtenha o título: <Highlight> Bloody War Soul </>",
  [611399063764992] = "Um símbolo de nova vida, frequentemente usado em rituais que envolvem destino, nascimento ou laços de sangue.",
  [611399063699456] = "Material do herói Inner City 1",
  [611399063635456] = "Após o uso, obtenha o título: <Highlight> Evernight Guardian </>",
  [611399063569920] = "Notas verdes e brancas, uma moeda relativamente comum no sistema monetário do Reino de Loen.",
  [611398258361088] = "Pálido morto",
  [611399600454144] = "Um puro cristal espiritual refinado a partir de um equipamento, emitindo uma luz brilhante como uma pequena mas poderosa estrela.",
  [611399600453888] = "Produzido na Ilha Blue Mountain, a maior ilha do Arquipélago Rorsted. Este lugar possui numerosos depósitos minerais, e Blue Mountain Crystal é uma variedade popular entre eles.",
  [611399600453632] = "Desta vez, girar a chave não é para destravar, mas para trancar algo.",
  [611399600453376] = "Produzido em uma mina em Coniston, Midseashire, Loen Kingdom. Embora toda a cidade tenha sido severamente devastada pela guerra, ela possui uma grande quantidade de materiais contendo espiritualidade . Por causa dos estranhos rumores que frequentemente cercam a mina, os trabalhadores só se atrevem a cavar em busca da pederneira na camada mais externa.",
  [611399600451840] = "Um selo de cera da civilização a vapor. Durante as reformas do Imperador Roselle, os documentos legais foram tratados com tanta importância como a tecnologia do vapor, e este selo de cera é a melhor prova disso.",
  [611399600451072] = "Uma página do Brass Book, prova de um desafio à honra.",
  [611399600450560] = "Misteriosa poeira estelar flutuando nas profundezas do Mundo Espiritual.",
  [611399600450304] = "Um pedaço de pergaminho amarelado com algumas linhas de encantamentos borrados escritos em Hermes antigo, sentindo vagamente a poderosa força espiritual conectada ao outro lado do contrato.",
  [611399600713728] = "Olhando para o alvo e segurando o cristal, o rosto e a figura da outra pessoa surgirão dentro do cristal. À medida que o cristal derrete e penetra na palma da mão, você se torna essa pessoa. Mas um rosto emprestado acabará por se dissipar; esta ilusão não permanecerá com você por muito tempo.",
  [611399600635904] = "A suavidade cortada ao nascer é a âncora inicial do destino.",
  [611399600615680] = "Um presente tão magnífico quanto uma estrela galopante ao entardecer, carregando os mais entusiásticos elogios do Espectador, fazendo uma aparição deslumbrante no Corredor Fantasma.",
  [611399600506368] = "Quando os moradores de Tingen entram em seus sonhos, alguém deve ficar acordado para lutar contra a loucura.",
  [611399600442368] = "Um Santo Graal especial capaz de se comunicar e conectar com o Mundo Espiritual. \n já foi uma peça da coleção da Rainha da Lua de Sangue, a \"Deusa da Beleza\" Olnia. Pode servir como um meio para formar temporariamente um pacto com criaturas do Mundo Espiritual leais à \"Deusa da Beleza\", levando-as a trazer itens divinos do Mundo Espiritual.",
  [611399600445440] = "Com isso como selo, sele outra aparência.",
  [611399600448256] = "Acumular conhecimento promove Agir, mas saber demais levará gradualmente à corrupção pela divindade. Isso traz poder, mas também loucura.",
  [611399600448000] = "Fragmentos de projeção flutuando na névoa da história.",
  [611399600447744] = "Uma ametista que traz boa sorte, pode ser usada para trocas em lojas.",
  [611399600447488] = "Não só representa recursos, mas também é uma prova poderosa dos esforços conjuntos de todos os sócios do clube na construção do clube. O clube compartilhará o mesmo destino de todos os seus membros.",
  [611399600447232] = "Usado para aumentar níveis e comprar peças de xadrez.",
  [611399600446976] = "Usado para comprar móveis e atualizar o Castelo.",
  [611399600446720] = "Lembre-se que você está apenas agindo",
  [611399600446464] = "Lembre-se, você está apenas agindo.",
  [611399600446208] = "Cada moeda de ouro representa o cumprimento de uma comissão, uma proteção compartilhada e uma honra compartilhada, condensando o pacto comum e a contribuição coletiva dos associados do clube.",
  [611399600445696] = "A luz da lua cai em cristais de gelo e o tempo para por isso. Por que não transformar este momento em eternidade?",
  [611399600445184] = "O gosto da moda é assim verificado.",
  [611399600444928] = "Uma tintura feita de materiais secretos que emite um brilho lustroso.",
  [611399600444672] = "Uma tintura especial feita de coral moído, com cores vibrantes e duradouras.",
  [611399600444416] = "Tintura transbordando de bolhas, colorida e fácil de aplicar.",
  [611399600444160] = "Puro orvalho com luz cintilante, é o tingimento preferido dos alfaiates, mas a fórmula é desenvolvida exclusivamente e conhecida por poucas pessoas no mundo.",
  [611399600443904] = "Espaço reservado",
  [611399600443648] = "Uma ferramenta de corte afiada capaz de cortar os fios do destino. Aqueles que dominam o destino também são controlados por ele; cada corte que fizer trará mudanças desconhecidas. Que a boa sorte esteja sempre com você.",
  [611399600443392] = "Uma moeda antiga com o brilho do céu estrelado, capaz de responder ao Mundo Espiritual e ao cosmos através do corpo espiritual . Gravado com inscrições secretas desenhadas por um anjo da família Abraão, cada uso é como iniciar uma viagem pelas estrelas, trazendo ao usuário insights e ganhos com a jornada.",
  [611399600443136] = "Um cartão contendo vasto espiritualidade . O titular pode usar este meio para se comunicar com o Mundo Espiritual, trocar sorte e destino e obter tesouros do Mundo Espiritual.",
  [611399600442880] = "Um cartão especial incrustado com pedras preciosas, contendo o conceito de “beleza” do Mundo Espiritual. Depois de ser trazido de volta à realidade pelas criaturas do Mundo Espiritual, ele pode se transformar em vários tipos dos mais preciosos itens colecionáveis ​​da Deusa da Beleza.",
  [611399063875072] = "Atualizar espaço reservado para item",
  [611399063874816] = "Item de atualização de equipamento de marca. \n pode atualizar <Highlight> Crimson Ember </> para <Highlight> Nível 62 Orange Quality </> , consumindo <Highlight> 1 </> Memory Crystal na atualização.",
  [611399063874560] = "Imprima o item de atualização do equipamento. \nPode atualizar <Highlight> Anel de Glória do Dragão </> para <Highlight> qualidade laranja de nível 62 </>. Consome <Highlight> 1 </> Time Sand ao atualizar.",
  [611399063874304] = "Imprima o item de atualização do equipamento. \nPode atualizar <Highlight> Botas de couro quentes </> para <Highlight> qualidade laranja nível 62 </>. Consome <Highlight> 1 </> Fragmento do Passado ao atualizar.",
  [611399063874048] = "Imprima o item de atualização do equipamento. \nPode atualizar <Highlight> Jester's Jest </> para <Highlight> qualidade laranja nível 62 </>. Consome <Highlight> 3 </> Beyonder Impressões ao atualizar.",
  [611399063873792] = "Imprima o item de atualização do equipamento. \nPode atualizar <Highlight> Restless Thorn </> para <Highlight> qualidade laranja nível 62 </>. Consome <Highlight> 3 </> Âncoras Históricas ao atualizar.",
  [611399063873536] = "Imprima o item de atualização do equipamento. \nPode atualizar <Highlight> Anel de Estagnação </> para <Highlight> qualidade laranja nível 62 </>. Consome <Highlight> 3 </> Espiritualidade Resonance Stones ao atualizar.",
  [611399063873280] = "Após o uso, obtenha o título: <Highlight> Estou de volta </>",
  [611399063873024] = "Após o uso, você pode realizar a <Highlight> Phantom Action - Blow Kiss Delivery </> no jogo Phantom of the Opera.",
  [611399063872768] = "Após o uso, você pode realizar a <Highlight> Phantom Action: Support Call </> no jogo Phantom of the Opera.",
  [611399063872512] = "Após o uso, você pode realizar a <Highlight> Phantom Action: Elegant Glance Back </> no jogo Phantom of the Opera.",
  [611399063872256] = "Após o uso, você pode realizar a <Highlight> Phantom Action: Sweet Charm Double </> no jogo Phantom of the Opera.",
  [611399063872000] = "Este voucher pode ser utilizado para deduzir 25% do preço unitário na liquidação de <Highlight> itens cosméticos de venda direta na loja </> . Podem ser utilizados no máximo 2 vouchers para um único item.",
  [611399063871744] = "Após o uso, obtenha o título: <Highlight> Amigo dos Babuínos </>",
  [611399063871488] = "Obtenha 1 <Highlight> Códice do Triunfo - Batalha pelo Trono de Deus </> e <Highlight> 25 Insígnias de Triunfo </>.",
