  [611399063790336] = "Obtido através da conversão da favorabilidade que transborda de vários modos de jogo após atingir a favorabilidade máxima com uma pessoa, e pode ser trocado na loja Past Exhibition Hall.",
  [611399063790080] = "Líquido extraído da raiz do papel, capaz de estabilizar a mente e aumentar a afinidade com textos e símbolos.",
  [611399063789824] = "Criado por um Beyonder com um Sequência superior a 'Scroll Professor', uma criação que sela conhecimento de alto nível e poder extraordinário, sua estrutura e princípios excedem em muito o escopo do entendimento comum.",
  [611399063789568] = "O resíduo após a queima de um espírito de papel, contendo informações fragmentadas e o conceito de Demise, muitas vezes usado para apagar ou confundir.",
  [611399063789312] = "Um líquido contendo Saúde vigorosa e afinidade natural, excelente meio de Cura e crescimento.",
  [611399063789056] = "Órgão visual composto de papel e artes secretas, capaz de ver através de disfarces ou criar ilusões indistinguíveis.",
  [611399063788800] = "O núcleo condensado da vida e sabedoria de um sacerdote ente, contendo profundo poder natural e memórias do tempo.",
  [611399063788544] = "As impressões mentais do misticismo antigo permanecem nas fibras do papel, capazes de ressoar com a frequência de Inspiração da época.",
  [611399063788288] = "Capaz de capturar fragmentos de pensamento remanescentes através de pós-imagens da alma.",
  [611399063788032] = "As penas são leves e emitem tons fracos espiritualidade .",
  [611399063787776] = "Possuindo um pulso selvagem de reação rápida, com percepção espiritual extremamente aguçada.",
  [611399063787520] = "A faixa Visão Espiritual é extremamente ampla, capaz de capturar ondulações de imagens de memórias e do futuro próximo.",
  [611399063787264] = "Dentro das fibras de queratina, existe espiritualidade natural para rastrear e fixar nos alvos.",
  [611399063787008] = "Possuindo um efeito de paralisia no corpo espiritual, tocá-lo pode bloquear rapidamente o fluxo mental.",
  [611399063786752] = "A queratina biológica contém espiritualidade pontiagudos, que podem facilmente cortar estruturas materiais.",
  [611399063786496] = "Baseada em cascas duras, a estrutura em treliça pode proteger a maioria das correntes espirituais de Impacto.",
  [611399063786240] = "Qualidade espiritual fluindo com músculos ativos, com frequência de pulsação extremamente alta.",
