  [611399063756288] = "Suco exalado naturalmente de frutas que amadurecem em julho, possuindo propriedades intoxicantes leves e efeitos de difusão espiritualidade.",
  [611399063756032] = "Ervas que só crescem no meio do verão, contendo saúde vigorosa, frequentemente usadas para melhorar o físico ou em fórmulas relacionadas à saúde.",
  [611399063755776] = "Vinho comum fermentado, frequentemente usado como meio ritual para amortecer o conflito entre o poder extraordinário e o corpo humano.",
  [611399063755520] = "Uma planta extraordinária que emite ressonância de baixa frequência ao vento, o que pode aumentar a ressonância mental e a estabilidade ritual.",
  [611399063755264] = "Cristais de girassol formados sob luz solar intensa ou durante rituais de fé do Sol Caminho, contendo luz estável e atributos de Purificação.",
  [611399063755008] = "Um pergaminho registrando a fórmula da poção para avançar para Sequência 8, fornecido pela Blackthorn Security Company aos membros ativos que acumularam pontos de contribuição suficientes após atingir um certo nível de progresso na digestão.",
  [611399063754752] = "Depois de obter este item místico, você ganhará a habilidade de atuação do mestre de armas Sequência. \n O cinto possui micro-runas que podem manifestar diversas armas durante uma apresentação.",
  [611399063754496] = "Depois de obter este item místico, você ganhará a habilidade de atuação do lutador Sequência. \n Braçadeiras que podem aumentar a força e explodir.",
  [611399063754240] = "Após obter este item místico, você ganhará a Habilidade de Atuação do Guerreiro Sequência. \n Um par de botas de ferro pesadas que podem criar vibrações e rachaduras ao pisar no chão.",
  [611399063753984] = "Depois de obter este item místico, você ganhará a habilidade de atuação do mago Sequência. \n Um disco gravado com runas complexas, que pode ser usado para realizar rituais.",
  [611399063753728] = "Depois de obter este item místico, você ganhará a habilidade de atuação do estudioso de luta Sequência. \n Um par de óculos antigos de bronze com lentes em ouro claro e armações gravadas com relevos de um falcão caçador e garras afiadas. Quando usado, o campo de visão estreita-se ligeiramente, mas todas as silhuetas parecem divididas em diferentes blocos de cores e linhas fluidas.",
  [611399063753472] = "Depois de obter este item místico, você ganhará a habilidade de atuação do Espreitador de Mistérios Sequência. \n Um pequeno pedaço de papel dobrado que revela informações ocultas na mão.",
  [611399063753216] = "Depois de obter este item místico, você ganhará a habilidade de atuação do astrólogo Sequência. \n Uma bola de cristal azul escuro com a luz das estrelas e uma leve névoa se movendo em seu interior. Mesmo com os olhos fechados, pode-se sentir seu pulso fraco, como se estivesse respirando.",
  [611399063752960] = "Depois de obter este item místico, você ganhará a habilidade de atuação do Trickmaster Sequência. \n Uma caixa de madeira preta aparentemente comum com um brilho translúcido, incrustada com sete pequenas pedras preciosas coloridas. Os itens retirados da caixa sempre carregam uma sensação de irrealidade e ocasionalmente se transformam em ilusões no ar. A caixa emite uma leve fragrância, mas às vezes o cheiro se transforma em um cheiro metálico confuso.",
  [611399063752704] = "Após obter este item místico, você ganhará a Habilidade de Atuação do Aprendiz Sequência. \n Uma chave de bronze antiga; quando inserido em qualquer fechadura de porta, o outro lado da porta levará a um local aleatório.",
  [611399063752448] = "Depois de obter este item místico, você ganhará a habilidade de atuação do psicólogo Sequência. \n Uma caneta de metal fina; símbolos escritos no ar entrarão na mente do alvo, ajustando seu estado emocional.",
  [611399063752192] = "Depois de obter este item místico, você ganhará a habilidade de atuação do leitor de mentes Sequência. \n Um anel escuro que, quando usado, permite ouvir o conteúdo emocional em que o alvo está pensando.",
  [611399063751936] = "Depois de obter este item místico, você ganhará a habilidade de atuação do espectador Sequência. \n Um pequeno espelho de cobre que reflete não a aparência de uma pessoa, mas as cores e halos de luz correspondentes ao seu humor.",
  [611399063751680] = "Depois de obter este item místico, você ganhará a habilidade de atuação do Sacerdote do Sol Sequência. \n Uma peça de ouro gravada com o emblema do sol, que pode liberar chamas sagradas durante a oração.",
  [611399063751424] = "Depois de obter este item místico, você ganhará a habilidade de atuação do buscador de luz Sequência. \n Uma antiga lâmpada de mão que pode cobrir o alvo com um brilho dourado pálido.",
  [611399063751168] = "Após obter este item místico, você ganhará a Habilidade de Atuação do Bardo Sequência. \n Uma pena de pássaro dourada que emite um brilho quente quando segurada na mão.",
  [611399063750912] = "Após obter este item místico, você ganhará a Habilidade de Atuação do Mago Sequência. \n Uma figura humanóide dobrada em uma fina tira de papel, com símbolos de vórtice desenhados em tinta nos olhos.",
  [611399063750656] = "Depois de obter este item místico, você ganhará a habilidade de atuação do palhaço Sequência. \n Uma estranha cesta redonda feita de tecido roxo escuro e dourado, com um rosto sorridente torto e um padrão espiral simbolizando o caos bordado na superfície.",
  [611399063750400] = "Depois de obter este item místico, você ganhará a habilidade de atuação do vidente Sequência. \n Uma corrente de prata com um fragmento arredondado de meteorito pendurado na ponta, incrustado com um cristal retirado de ruínas antigas no meio.",
  [611399063750144] = "Obtido ao completar missões diárias de Easy Winning, pode ser usado para trocar por materiais de poções.",
