  [611399063662080] = "Duas batatas",
  [611399063661824] = "Consumir vitalidade pode desbloquear <Highlight> tesouros de aventura mundial, guerra por guerra e presentes sociais </>. \n \n Vitalidade pode ser obtida através de <Highlight> missões Easy Winning </> ou <Highlight> recuperação natural </>, ou você pode usar <Highlight> Vitality Sugar Cubes </> para se recuperar rapidamente.",
  [611399063661568] = "Pode ser obtido participando de vários modos de jogo, pode ser usado na Loja de Reembolsos para resgatar diversas recompensas. \n\nO limite semanal de recebimento de faturas é de 10.000, que podem ser acumuladas por até 2 semanas. O limite de aquisição de recebimentos de faturas é atualizado toda segunda-feira às 8h.",
  [611399063661312] = "Pontos de atividades do clube, que podem ser obtidos participando das missões do Subsídio para Atividades do Clube.",
  [611399063660544] = "Pode ser obtido participando de vários modos competitivos e usado na Triumph Shop.",
  [611399063660288] = "Item temporário",
  [611399063659776] = "<Highlight> Tentativas restantes para a Semente dos Suspiros: Disputa de Monstros missão </> . O objetivo missão é <Highlight> ir para a área de disputa designada para aceitar e derrotar o monstro de teste </>.",
  [611399063659264] = "Pontos de vitória para o modo Final Hunt, que podem ser obtidos <Highlight> reivindicando recompensas semanais de nível de progresso de caça </> ou <Highlight> saqueando-os matando outros jogadores hostis </> .",
  [611399063659008] = "Convoque uma Vanguarda da Calamidade no [Calamity Lair]. Derrotá-lo concederá Relíquia Escarlate materiais. A Vanguarda da Calamidade é poderosa; é recomendado <Highlight> formar uma equipe para desafiá-lo </> .",
  [611399063658752] = "<Highlight> Somente durante o evento Hunting Time </> , você pode invocar um Fate Marionete no [Altar of Fate]. Derrotá-lo concederá Relíquia Escarlate materiais. A área da Cidade Real está repleta de perigos; é recomendado que uma equipe <Highlight> vá desafiá-lo </> .",
  [611399063658240] = "<Highlight> Tentativas restantes para a Semente dos Suspiros: Caça aos Monstros missão </> . O objetivo missão é <Highlight> encontrar e derrotar os cavaleiros que vagam pela Cidade da Caça ao Dragão </>.",
  [611399063657984] = "<Highlight> Depois de aceitar a Semente dos Suspiros missão </> , Relíquias Escarlates pode ser obtido matando <Highlight> Beyonder criaturas na Cidade de Caça ao Dragão </> ou derrotando outros jogadores hostis <Highlight> para saqueá-los </> . Quando morto por um jogador inimigo, <Highlight> Relíquias Escarlates também será descartado proporcionalmente </> . \n Você pode enviá-los para o <Highlight> [Hunting Butler] </> para avançar <Highlight> recompensas de progresso de caça </>. <Highlight> Relíquias Escarlates só são efetivos dentro da Cidade de Caça ao Dragão </> ; ao sair, eles <Highlight> expirarão automaticamente e serão liberados </> .",
  [611399063657728] = "Relíquia Escarlate (Bound) pode ser obtido matando Beyonder criaturas na <Highlight> City of Dragon Hunting </>. Quando morto por um jogador inimigo, <Highlight> Relíquia Escarlate (Bound) não será descartado </> . \n Você pode enviá-lo para o <Highlight> [Hunting Butler] </> para avançar <Highlight> recompensas de progresso de caça </>.",
  [611399063657472] = "O progresso da caça só pode ser obtido enviando <Highlight> Relíquias Escarlates </> para o <Highlight> \"Hunt Butler\" </> no <Highlight> modo End-of-Days Hunt </>.",
